package it.cavallium.rockserver.core.impl.test;

import it.cavallium.rockserver.core.common.distributed.*;
import it.cavallium.rockserver.core.impl.rocksdb.*;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** Trusted native learner foundation only; no runtime authority, promotion, server or quorum claim. */
class NativeTopologyLearnerTest {
    @TempDir(factory=DiskTestDirectory.class) Path root;
    final NativeTopologyImageTest helper=new NativeTopologyImageTest();
    final ReplicaDescriptor learner=new ReplicaDescriptor(new UUID(0,991),new UUID(0,992),new UUID(0,993),"learner","localhost:19993",ReplicaDescriptor.Role.LISTENER);
    TopologyChange.Definition relocation(NativeTopologyImageTest.Fixture source) {
        var directory=source.definition.targetDirectory();var target=directory.ranges().getFirst();var replicas=new ArrayList<>(target.replicas());replicas.add(learner);var changed=new RangeDescriptor(target.rangeId(),target.groupId(),target.rangeEpoch(),target.configurationVersion()+1,target.lowerInclusive(),target.upperExclusive(),target.topologyState(),replicas);
        var ranges=new ArrayList<>(directory.ranges());ranges.set(0,changed);var proposed=new RangeDirectory(directory.clusterId(),directory.databaseId(),directory.domainId(),directory.schemaEpoch(),directory.schemaDigest(),directory.generation()+1,directory.columns(),directory.routingPrefixBytes(),ranges);return new TopologyChange.Definition(new UUID(0,994),TopologyChange.Kind.RELOCATE,directory,proposed);
    }
    NativeTopologyLearnerRegistration registration(NativeTopologyImageTest.Fixture source,NativeRangeImage.Manifest image) {
        return new NativeTopologyLearnerRegistration(relocation(source),image.topologyOrigin(),helper.helper.outer.schema(),learner,helper.catalogue,new ApplyPosition(1,20),image.position(),image.sha256(),new byte[]{1},new byte[]{2},helper.names(""),Set.of());
    }
    @Test void sourceImageKeepsOriginalOwnerProvenanceWhileReceiverInstallsReplaysTailAndRemainsBusinessFenced()throws Exception {
        Path imagePath=root.resolve("image"),receiverPath=root.resolve("receiver");NativeTopologyLearnerRegistration registration;DistributedCommand original;byte[] originalResult;
        try(var source=helper.new Fixture(root.resolve("source"),helper.first,"")) {
            source.cdc();original=source.write(8);originalResult=source.child.apply(new ApplyPosition(1,2),original);var image=NativeRangeImage.write(imagePath,source.child,helper.limits);registration=registration(source,image);
            assertEquals(registration,NativeTopologyLearnerRegistration.decode(registration.encode()));for(int length:List.of(0,3,registration.encode().length-1)){byte[] truncated=Arrays.copyOf(registration.encode(),length);assertThrows(IllegalArgumentException.class,()->NativeTopologyLearnerRegistration.decode(truncated));}
            try(var pool=helper.helper.pool(receiverPath)) {
                var receiver=pool.openTopologyLearner(registration);assertEquals(RangeOwnership.State.FENCED,receiver.ownership().state());assertNull(receiver.applied());assertTrue(receiver.topologyBirthPending());assertThrows(IllegalStateException.class,receiver::activate);assertThrows(IllegalStateException.class,receiver::capture);assertThrows(IllegalStateException.class,()->receiver.applyTopologyLearnerTail(new ApplyPosition(1,3),original));assertFalse(receiver.topologyLearnerReadiness(new ApplyPosition(1,4)).ready());
                receiver.enableCdc(registration.definition().parents().getFirst().rangeId());receiver.installSnapshot(imagePath,helper.limits);assertEquals(image.position(),receiver.applied());assertArrayEquals(registration.origin().activation().encode(),receiver.topologyActivation().encode());assertEquals(registration.origin().activation().birth(),receiver.topologyBirth());assertTrue(pool.topologySeeds().isEmpty());assertArrayEquals(originalResult,receiver.operationResult(original.operationId(),original.receiptDigest()));assertEquals(helper.first.replicaId(),receiver.topologyActivation().proof().owner().replicaId());assertNotEquals(learner.replicaId(),receiver.topologyActivation().proof().owner().replicaId());
                assertThrows(IllegalStateException.class,()->receiver.apply(new ApplyPosition(1,3),source.write(9)));var tail=new DistributedCommand(original.groupId(),1,receiver.schemaDigest(),new OperationId(original.operationId().sessionId(),1,1),List.of(new Mutation(Mutation.Kind.PUT,helper.helper.outer.fixed,helper.helper.helper.key(1),helper.helper.helper.key(9))));receiver.applyTopologyLearnerTail(new ApplyPosition(1,3),tail);assertFalse(receiver.topologyLearnerReadiness(new ApplyPosition(1,3)).ready());receiver.applyNoop(new ApplyPosition(1,4),registration.proposedConfiguration());assertTrue(receiver.topologyLearnerReadiness(new ApplyPosition(1,4)).ready());receiver.applyNoop(new ApplyPosition(2,5));assertFalse(receiver.topologyLearnerReadiness(new ApplyPosition(1,5)).ready());assertTrue(receiver.topologyLearnerReadiness(new ApplyPosition(2,5)).ready());assertFalse(receiver.topologyLearnerReadiness(new ApplyPosition(2,6)).ready());assertThrows(IllegalStateException.class,receiver::activate);assertThrows(IllegalStateException.class,()->receiver.readCurrentPoint(helper.helper.outer.fixed,helper.helper.helper.key(1)));
                try(var pin=receiver.captureForRecovery()) {assertArrayEquals(helper.helper.helper.key(9),pin.get(helper.helper.outer.fixed,helper.helper.helper.key(1)));assertThrows(IllegalStateException.class,()->receiver.installSnapshot(imagePath,helper.limits));}assertSame(receiver,pool.openTopologyLearner(registration));
            }
        }
        try(var pool=helper.helper.pool(receiverPath)) {assertEquals(1,pool.topologyLearners().size());var receiver=pool.openTopologyLearner(registration);assertEquals(new ApplyPosition(2,5),receiver.applied());assertArrayEquals(registration.origin().activation().encode(),receiver.topologyActivation().encode());assertTrue(receiver.topologyLearnerReadiness(new ApplyPosition(1,4)).ready());assertThrows(IllegalStateException.class,receiver::activate);assertTrue(pool.topologySeeds().isEmpty());}
    }
    @Test void registrationColdReopenAndInterruptedImageRetryRetainReceiverAuthorityWithoutInventingAppliedCut()throws Exception {
        Path imagePath=root.resolve("image"),receiverPath=root.resolve("receiver");NativeTopologyLearnerRegistration registration;
        try(var source=helper.new Fixture(root.resolve("source"),helper.first,"")) {source.child.apply(new ApplyPosition(1,2),source.write(8));var image=NativeRangeImage.write(imagePath,source.child,helper.limits);registration=registration(source,image);try(var pool=helper.helper.pool(receiverPath)){var receiver=pool.openTopologyLearner(registration);assertNull(receiver.applied());assertThrows(IllegalStateException.class,receiver::activate);}}
        try(var pool=helper.helper.pool(receiverPath)) {var receiver=pool.openTopologyLearner(registration);assertNull(receiver.applied());assertEquals(registration,receiver.topologyLearnerRegistration());assertThrows(IllegalStateException.class,()->receiver.installSnapshot(imagePath,helper.limits,batches->{throw new IllegalStateException("interrupt native image import");}));assertTrue(receiver.pendingInstallation());assertNull(receiver.applied());assertEquals(registration,receiver.topologyLearnerRegistration());}
        try(var pool=helper.helper.pool(receiverPath)) {var receiver=pool.openTopologyLearner(registration);assertTrue(receiver.pendingInstallation());receiver.installSnapshot(imagePath,helper.limits);assertFalse(receiver.pendingInstallation());assertEquals(registration.imageCut(),receiver.applied());assertEquals(registration,receiver.topologyLearnerRegistration());assertArrayEquals(registration.origin().activation().encode(),receiver.topologyActivation().encode());}
    }
    @Test void changedImageIncarnationAndUnqualifiedOldMemberCannotAdoptRemoteBirth()throws Exception {
        Path imagePath=root.resolve("image");try(var source=helper.new Fixture(root.resolve("source"),helper.first,"")) {
            source.child.apply(new ApplyPosition(1,2),source.write(8));var image=NativeRangeImage.write(imagePath,source.child,helper.limits);var registration=registration(source,image);
            try(var pool=helper.helper.pool(root.resolve("unqualified"))) {var target=source.definition.targets().getFirst();var receiver=helper.helper.open(pool,target);receiver.fence();assertThrows(java.io.IOException.class,()->receiver.installSnapshot(imagePath,helper.limits));assertNull(receiver.applied());}
            try(var pool=helper.helper.pool(root.resolve("qualified"))) {var receiver=pool.openTopologyLearner(registration);byte[] changed=registration.imageHash();changed[0]^=1;var different=new NativeTopologyLearnerRegistration(registration.definition(),registration.origin(),registration.schema(),learner,registration.catalogue(),registration.catalogueCut(),registration.imageCut(),changed,registration.sourceConfiguration(),registration.proposedConfiguration(),registration.physicalNames(),registration.mergeColumns());assertThrows(IllegalArgumentException.class,()->pool.openTopologyLearner(different));assertNull(receiver.applied());}
            var foreign=new ReplicaDescriptor(learner.nodeId(),UUID.randomUUID(),learner.replicaId(),learner.peerId(),learner.address(),learner.role());assertThrows(IllegalArgumentException.class,()->new NativeTopologyLearnerRegistration(registration.definition(),registration.origin(),registration.schema(),foreign,registration.catalogue(),registration.catalogueCut(),registration.imageCut(),registration.imageHash(),registration.sourceConfiguration(),registration.proposedConfiguration(),registration.physicalNames(),registration.mergeColumns()));
        }
    }
    NativeTopologyLearnerRegistration independentSource(int number)throws Exception {
        var schema=helper.helper.outer.schema();var template=helper.definition();var parentTemplate=template.parents().getFirst();
        var parent=new RangeDescriptor(parentTemplate.rangeId(),parentTemplate.groupId(),1,1,null,null,RangeDescriptor.TopologyState.ACTIVE,List.of(helper.first));var targets=new ArrayList<RangeDescriptor>();
        for(int n=0;n<2;n++){var target=template.targets().get(n);targets.add(new RangeDescriptor(target.rangeId(),new UUID(0,1000+number*2+n),1,1,target.lowerInclusive(),target.upperExclusive(),target.topologyState(),List.of(helper.first)));}
        var definition=new TopologyChange.Definition(new UUID(0,1200+number),helper.helper.topology.directory(schema,1,List.of(parent)),helper.helper.topology.directory(schema,2,targets));var imagePath=root.resolve("pending-image-"+number);
        NativeRangeImage.Manifest image;
        try(var pool=helper.helper.pool(root.resolve("pending-source-"+number))) {var source=helper.helper.open(pool,parent);source.initializeConfiguration(new byte[]{1});source.applyNoop(new ApplyPosition(1,0));var freeze=source.applyTopologyFreeze(new ApplyPosition(1,1),definition,helper.admission(definition));var authority=TopologyChange.State.begin(definition.header()).beginFencing().frozen(freeze.proof(helper.first.replicaId()));var seed=pool.seedTopology(definition,authority,List.of(source),helper.first);var child=pool.reopenTopologyRange(seed.birth(targets.getFirst().groupId()),schema);child.initializeConfiguration(new byte[]{1});child.applyNoop(new ApplyPosition(1,0));child.applyTopologyActivation(new ApplyPosition(1,1),definition,authority.freezeDigest(),helper.catalogue,helper.catalogueCut,NativeTopologyActivation.publicationCommitment(definition,authority.freezeDigest(),helper.catalogue));image=NativeRangeImage.write(imagePath,child,helper.limits);}
        var directory=definition.targetDirectory();var target=targets.getFirst();var replicas=new ArrayList<>(target.replicas());replicas.add(learner);var changed=new RangeDescriptor(target.rangeId(),target.groupId(),1,2,target.lowerInclusive(),target.upperExclusive(),target.topologyState(),replicas);var ranges=List.of(changed,targets.getLast());var proposed=helper.helper.topology.directory(schema,3,ranges);var relocation=new TopologyChange.Definition(new UUID(0,1300+number),TopologyChange.Kind.RELOCATE,directory,proposed);
        return new NativeTopologyLearnerRegistration(relocation,image.topologyOrigin(),schema,learner,helper.catalogue,new ApplyPosition(1,20+number),image.position(),image.sha256(),new byte[]{1},new byte[]{2},helper.names(""),Set.of());
    }
    @Test void unknownForceRetainsBoundedPendingChargesAndOnlyExactOriginalRetryCanPublish()throws Exception {
        var registrations=new ArrayList<NativeTopologyLearnerRegistration>();for(int n=0;n<9;n++)registrations.add(independentSource(n));var first=registrations.getFirst();Path receiverPath=root.resolve("pending-receiver");
        try(var pool=helper.helper.pool(receiverPath)) {
            pool.topologyLearnerForceObserver(after->{throw new org.rocksdb.RocksDBException("unknown learner force before persistence");});
            for(int n=0;n<8;n++){var registration=registrations.get(n);assertThrows(org.rocksdb.RocksDBException.class,()->pool.openTopologyLearner(registration));}assertTrue(pool.topologyLearners().isEmpty());assertThrows(IllegalStateException.class,()->pool.openTopologyLearner(registrations.getLast()));assertThrows(org.rocksdb.RocksDBException.class,()->pool.openTopologyLearner(first));
            byte[] changed=first.imageHash();changed[0]^=1;var different=new NativeTopologyLearnerRegistration(first.definition(),first.origin(),first.schema(),first.receiver(),first.catalogue(),first.catalogueCut(),first.imageCut(),changed,first.sourceConfiguration(),first.proposedConfiguration(),first.physicalNames(),first.mergeColumns());assertThrows(IllegalArgumentException.class,()->pool.openTopologyLearner(different));
            pool.topologyLearnerForceObserver(after->{if(after)throw new org.rocksdb.RocksDBException("unknown learner force after persistence");});assertThrows(org.rocksdb.RocksDBException.class,()->pool.openTopologyLearner(first));assertTrue(pool.topologyLearners().isEmpty());assertThrows(IllegalStateException.class,()->pool.openTopologyLearner(registrations.getLast()));pool.topologyLearnerForceObserver(after->{});
            assertThrows(IllegalStateException.class,()->pool.openTopologyLearner(registrations.get(1)));UUID ordinaryGroup=new UUID(0,9000),ordinaryColumn=new UUID(0,9001);assertThrows(IllegalStateException.class,()->pool.openRange(new RangeOwnership.Owner(ordinaryGroup,1),new RangeOwnership.Interval(new UUID(0,9002),Set.of(ordinaryColumn),null,null),new byte[32],Map.of(ordinaryColumn,"ordinary-history"),Set.of()));
            var receiver=pool.openTopologyLearner(first);assertEquals(first,receiver.topologyLearnerRegistration());assertNull(receiver.applied());assertEquals(1,pool.topologyLearners().size());assertSame(receiver,pool.openTopologyLearner(first));assertThrows(IllegalStateException.class,()->pool.openTopologyLearner(registrations.getLast()));var ordinary=pool.openRange(new RangeOwnership.Owner(ordinaryGroup,1),new RangeOwnership.Interval(new UUID(0,9002),Set.of(ordinaryColumn),null,null),new byte[32],Map.of(ordinaryColumn,"ordinary-history"),Set.of());assertNull(ordinary.applied());
        }
        try(var pool=helper.helper.pool(receiverPath)) {assertEquals(List.of(first),pool.topologyLearners());var receiver=pool.openTopologyLearner(first);assertEquals(first,receiver.topologyLearnerRegistration());assertNull(receiver.applied());}
    }

}
